// Shared browser/local public-market stream. Anomaly warnings only, never entry confirmation.
export const impulseTime=v=>{const n=Number(v);return !Number.isFinite(n)||n<=0?NaN:n>1e14?n/1000:n>1e11?n:n*1000};
const step=300000;
const numeric=v=>v===null||v===''||v===undefined?NaN:Number(v);
const valid=c=>c&&Object.values(c).every(Number.isFinite)&&c.time%step===0&&c.low>0&&c.high>=Math.max(c.open,c.close)&&c.low<=Math.min(c.open,c.close)&&c.volume>=0;
export function impulseEvaluate(history,current,sourceAt,now=Date.now()){
 if(!valid(current)||!Number.isFinite(sourceAt)||sourceAt>now+1000||now-sourceAt>15000||current.time!==Math.floor(sourceAt/step)*step)return null;
 const prior=history.filter(c=>c.time<current.time).slice(-20);
 if(prior.length!==20||prior.some((c,i)=>!valid(c)||c.time!==current.time-(20-i)*step))return null;
 const average=prior.reduce((n,c)=>n+c.volume,0)/20;if(!(average>0))return null;
 const ratio=current.volume/average,change=(current.close/current.open-1)*100,side=change>=0?1:-1,level=side===1?Math.max(...prior.map(c=>c.high)):Math.min(...prior.map(c=>c.low)),span=current.high-current.low,edge=span>0?(side===1?(current.close-current.low)/span:(current.high-current.close)/span):0;
 if(ratio<3||Math.abs(change)<1||side*(current.close-level)<=0||edge<.75)return null;
 return {side,ratio,changePercent:change,level,price:current.close,candleAt:current.time,sourceAt,at:now,forming:true,kind:'impulse'};
}
// Revalidates the ORIGINAL breakout reference, not profitability or a new entry.
export function impulseRevalidate(event,snapshot,{active=false,connected=false,universeAt=0,error=null,now=Date.now()}={}){
 const base={checkedAt:now,sourceAt:Number.isFinite(snapshot?.at)&&snapshot.at>0&&snapshot.at<=now+1000?snapshot.at:null,price:Number.isFinite(snapshot?.price)&&snapshot.price>0?snapshot.price:null,source:snapshot?.source??null,level:event.level,expiresAt:event.at+600000};
 const result=(status,reason)=>({...base,status,reason});const direction=event.side===-1?'breakdown':'breakout',position=event.side===-1?'below':'above';
 if(!Number.isFinite(event.at)||event.at>now+1000||!Number.isFinite(event.level)||event.level<=0||![1,-1].includes(event.side))return result('UNVERIFIED','Original warning reference is incomplete');
 if(now-event.at>600000)return result('EXPIRED','Original warning is over 10 minutes old; wait for a new setup');
 if(event.invalidatedAt)return result('INVALIDATED','Price returned inside the original range; this warning is retired');
 if(!active)return result('PAUSED','Monitoring is paused; current validity is not verified');
 if(!connected||error||now-universeAt>180000||universeAt>now+1000)return result('UNVERIFIED','Live connection or market coverage is unavailable');
 if(!Number.isFinite(snapshot?.at)||snapshot.at<=0||!Number.isFinite(snapshot?.price)||snapshot.price<=0)return result('WAITING','Waiting for a fresh price from this coin');
 if(snapshot.at>now+1000||now-snapshot.at>15000)return result('STALE','No fresh price for this coin within 15 seconds');
 if(event.side*(snapshot.price-event.level)<=0)return result('INVALIDATED','Price is back inside the original range');
 return result('HOLDING','Fresh price is '+position+' the original '+direction+' level; this is not a new entry confirmation');
}
export function createImpulseStream({fetchJson,WebSocket:Socket=globalThis.WebSocket,now=Date.now,onAlert=()=>{},onHistory=()=>{},onChange=null,interval=setInterval,clear=clearInterval,timeout=setTimeout,cancel=clearTimeout}={}){
 let active=false,generation=0,ws=null,retry=null,timer=null,busy=false,lastReceivedAt=null,lastSourceAt=null,error=null,attempt=0,universeAt=0,lastEmitAt=-Infinity,notifyPending=null,quoteBusy=false;
 const markets=new Map(),events=[],seen=new Map();
 const status=()=>({prices:Object.fromEntries([...new Set([...markets.keys()].slice(0,20).concat(events.map(e=>e.symbol)))].map(symbol=>[symbol,{price:markets.get(symbol)?.lastPrice??null,sourceAt:markets.get(symbol)?.lastAt??null,source:markets.get(symbol)?.lastPriceSource??null}])),active,connected:ws?.readyState===1,total:markets.size,ready:[...markets.values()].filter(m=>Array.from({length:20},(_,i)=>Math.floor(now()/step)*step-(20-i)*step).every(t=>m.bars.some(c=>c.time===t))).length,baselineErrors:[...markets.values()].filter(m=>m.error).length,lastReceivedAt,lastSourceAt,error,events:events.map(e=>({...e,validation:impulseRevalidate(e,{at:markets.get(e.symbol)?.lastAt,price:markets.get(e.symbol)?.lastPrice,source:markets.get(e.symbol)?.lastPriceSource},{active,connected:ws?.readyState===1,universeAt,error,now:now()})})),universeAt});
 const emit=(force=false)=>{if(typeof onChange!=='function')return;if(force||now()-lastEmitAt>=250){cancel(notifyPending);notifyPending=null;lastEmitAt=now();onChange(status())}else if(notifyPending===null)notifyPending=timeout(()=>{notifyPending=null;lastEmitAt=now();onChange(status())},250)};
 const historyChanged=()=>Promise.resolve().then(()=>onHistory(events.map(({validation,...e})=>({...e})))).catch(()=>{error='Warning history could not be saved';emit()});
 const isCurrent=g=>active&&g===generation;
 function observe(symbol,price,at,source){const m=markets.get(symbol);if(!m||!(price>0)||!Number.isFinite(price)||!Number.isFinite(at)||at>now()+1000||now()-at>15000||at<(m.lastAt??0))return false;m.lastAt=at;m.lastPrice=price;m.lastPriceSource=source;lastReceivedAt=now();lastSourceAt=Math.max(lastSourceAt??0,at);let retired=false;for(const e of events)if(e.symbol===symbol&&!e.invalidatedAt&&now()-e.at<=600000&&at>=(e.sourceAt??e.at-15000)&&Number.isFinite(e.level)&&e.side*(price-e.level)<=0){e.invalidatedAt=now();e.invalidatedPrice=price;retired=true}if(retired)historyChanged();return true}
 async function refreshWarningPrices(g){if(!isCurrent(g)||quoteBusy)return;const symbols=[...new Set(events.filter(e=>!e.invalidatedAt&&now()-e.at<=600000).map(e=>e.symbol))].filter(s=>{const m=markets.get(s);return m&&now()-(m.lastAt??0)>10000&&now()-(m.quoteAttemptAt??0)>=10000}).slice(0,2);if(!symbols.length)return;quoteBusy=true;try{await Promise.all(symbols.map(async symbol=>{const m=markets.get(symbol);m.quoteAttemptAt=now();try{const raw=await fetchJson('/v2/tickers/'+symbol);if(!isCurrent(g)||markets.get(symbol)!==m)return;const d=raw?.result??raw;if(d?.symbol!==symbol)return;observe(symbol,numeric(d.close),impulseTime(d.timestamp),'REST ticker')}catch{}}));if(isCurrent(g))emit()}finally{quoteBusy=false}}
 function stop(){active=false;generation++;cancel(retry);cancel(notifyPending);notifyPending=null;clear(timer);retry=timer=null;const old=ws;ws=null;old?.close();markets.clear();lastReceivedAt=lastSourceAt=null;emit(true)}
 function reconnect(g){if(!isCurrent(g))return;const old=ws;ws=null;old?.close();cancel(retry);retry=timeout(()=>connect(g),Math.min(30000,1000*2**Math.min(attempt++,5)));error='Stream reconnecting; warnings unavailable until fresh messages resume';emit()}
 function connect(g){if(!isCurrent(g)||!markets.size)return;lastReceivedAt=lastSourceAt=null;for(const m of markets.values()){m.lastAt=null;m.lastPrice=null;m.lastCandleAt=null;m.lastPriceSource=null}try{const socket=new Socket('wss://public-socket.india.delta.exchange');ws=socket;let openedAt=now();socket.onopen=()=>{if(!isCurrent(g)||ws!==socket){socket.close();return}socket.send(JSON.stringify({type:'subscribe',payload:{channels:[{name:'candlestick_5m',symbols:[...markets.keys()]},{name:'ticker',symbols:[...markets.keys()]}]}}));emit()};socket.onmessage=e=>{if(!isCurrent(g)||ws!==socket)return;try{const d=JSON.parse(e.data);if(d.type==='error'){error='Exchange rejected stream subscription';emit();return}if(d.type==='ticker'){const at=impulseTime(d.ts);if(Array.isArray(d.d)&&now()-universeAt<=180000){let accepted=false;for(const row of d.d){if(!row||!Array.isArray(row.ohlc)||row.ohlc.length!==4)continue;accepted=observe(row.s,numeric(row.ohlc[3]),at,'Ticker stream')||accepted}if(accepted){attempt=0;error=null;emit()}}return}if(d.type!=='candlestick_5m')return;if(now()-universeAt>180000){error='Liquidity universe is stale; warnings paused until refresh';emit();return}const at=impulseTime(d.ts),m=markets.get(d.sy);if(!m||!Number.isFinite(at)||at>now()+1000||now()-at>15000||at<(m.lastCandleAt??0))return;const c={time:d.cst?impulseTime(d.cst):Math.floor(at/step)*step,open:numeric(d.o),high:numeric(d.h),low:numeric(d.l),close:numeric(d.c),volume:numeric(d.v)};if(!valid(c)||c.time!==Math.floor(at/step)*step)return;
 // Reject regressing cumulative volume / older updates within a candle.
 const previous=m.bars.find(x=>x.time===c.time);if(previous&&c.volume<previous.volume)return;
 m.lastCandleAt=at;observe(d.sy,c.close,at,'Candle stream');attempt=0;error=null;const signal=impulseEvaluate(m.bars,c,at,now());m.bars=m.bars.filter(x=>x.time!==c.time).concat(c).sort((a,b)=>a.time-b.time).slice(-24);
 if(signal&&signal.side*(m.lastPrice-signal.level)>0){const key=['impulse','delta',d.sy,signal.side,c.time].join(':'),cooldown=d.sy+':'+signal.side;if(!seen.has(key)&&now()-(seen.get(cooldown)??-Infinity)>=1800000){seen.set(key,now());seen.set(cooldown,now());for(const [k,t]of seen)if(now()-t>86400000)seen.delete(k);const time=new Date(now()).toLocaleTimeString('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}),event={...signal,key,symbol:d.sy,exchange:'delta',quote:'USD',title:`VOLUME SURGE · ${d.sy} · ${signal.side===1?'UP':'DOWN'} ${Math.abs(signal.changePercent).toFixed(1)}% · ${signal.ratio.toFixed(1)}× VOLUME · ${time} IST · FORMING`};events.unshift(event);events.splice(40);historyChanged();Promise.resolve(onAlert(event)).catch(()=>{error='Warning persistence unavailable';emit()})}}emit();}catch{}};socket.onerror=()=>{};socket.onclose=()=>{if(isCurrent(g)&&ws===socket)reconnect(g)};socket._radarOpenedAt=openedAt;}catch{reconnect(g)}}
 async function seed(symbol,g){const m=markets.get(symbol);if(!m||m.loading||now()-(m.seedAt??0)<30000)return;m.loading=true;try{const end=Math.floor(now()/1000),raw=await fetchJson('/v2/history/candles?resolution=5m&symbol='+symbol+'&start='+(end-300*26)+'&end='+end);if(!isCurrent(g)||markets.get(symbol)!==m)return;const values=raw?.result??raw;if(!Array.isArray(values))throw Error('Candle baseline unavailable');const parsed=new Map();for(const r of values){const c={time:numeric(r.time)*1000,open:numeric(r.open),high:numeric(r.high),low:numeric(r.low),close:numeric(r.close),volume:numeric(r.volume)};if(!valid(c)||c.time>Math.floor(now()/step)*step)throw Error('Invalid candle baseline');if(parsed.has(c.time)&&JSON.stringify(parsed.get(c.time))!==JSON.stringify(c))throw Error('Conflicting candle baseline');parsed.set(c.time,c)}for(const c of m.bars)if(c.time===Math.floor(now()/step)*step&&(!parsed.has(c.time)||c.volume>=parsed.get(c.time).volume))parsed.set(c.time,c);m.bars=[...parsed.values()].sort((a,b)=>a.time-b.time).slice(-24);m.seedAt=now();m.error=null;}catch{if(isCurrent(g)){m.error='Candle baseline unavailable';m.seedAt=now()}}finally{m.loading=false}}
 async function tick(g){if(!isCurrent(g)||busy)return;busy=true;try{if(now()-universeAt>60000||!markets.size){const raw=await fetchJson('/v2/tickers?contract_types=perpetual_futures');if(!isCurrent(g))return;const rows=raw?.result??raw;if(!Array.isArray(rows)||!rows.length)throw Error('Market list unavailable');const eligible=rows.filter(r=>r.contract_type==='perpetual_futures'&&/^[A-Z0-9]+USD$/.test(r.symbol)&&Number.isFinite(Number(r.turnover_usd))&&Number(r.turnover_usd)>=0).sort((a,b)=>Number(b.turnover_usd)-Number(a.turnover_usd));const names=new Set(eligible.map(r=>r.symbol));let changed=false;for(const s of markets.keys())if(!names.has(s)){markets.delete(s);changed=true}for(const s of names)if(!markets.has(s)){markets.set(s,{bars:[],loading:false,seedAt:0});changed=true}universeAt=now();if(changed||!ws)connectReplace(g);}
 const floor=Math.floor(now()/step)*step;const need=[...markets].filter(([,m])=>!Array.from({length:20},(_,i)=>floor-(20-i)*step).every(t=>m.bars.some(c=>c.time===t))).filter(([,m])=>!m.loading&&now()-(m.seedAt??0)>=30000).sort((a,b)=>(a[1].seedAt??0)-(b[1].seedAt??0)).slice(0,3);await Promise.all(need.map(([s])=>seed(s,g)));if(!isCurrent(g))return;
 emit();}catch{if(isCurrent(g)){error='Public market feed unavailable; coverage cannot be verified';emit()}}finally{busy=false}}
 function connectReplace(g){lastReceivedAt=null;lastSourceAt=null;cancel(retry);const old=ws;ws=null;old?.close();connect(g)}
 function start(){if(active)return;active=true;const g=++generation;tick(g);timer=interval(()=>{if(isCurrent(g)&&ws&&now()-(lastReceivedAt??ws._radarOpenedAt)>35000)reconnect(g);refreshWarningPrices(g);tick(g)},2000);timer?.unref?.();emit()}
 return {start,stop,status,restore(saved){for(const e of (Array.isArray(saved)?saved:[]).filter(e=>e&&typeof e==='object'&&typeof e.key==='string'&&e.key.length<=180&&typeof e.symbol==='string'&&/^[A-Z0-9]+USD$/.test(e.symbol)&&[1,-1].includes(e.side)&&e.kind==='impulse'&&Number.isFinite(e.at)&&now()-e.at<86400000&&e.at<=now()).slice(0,40)){if(events.some(x=>x.key===e.key))continue;const {validation,...stored}=e;events.push(stored);seen.set(e.key,e.at);seen.set(e.symbol+':'+e.side,Math.max(seen.get(e.symbol+':'+e.side)??0,e.at))}events.sort((a,b)=>b.at-a.at);events.splice(40)},tick:()=>tick(generation)};
}
